 public static async Task RunAsync(){int n=0;void Check(bool v,string why){if(!v)throw new Exception(why);n++;}void Reject(Action a,string why){try{a();throw new Exception("accepted "+why);}catch(Exception e)when(e is ArgumentException or IOException or InvalidDataException){Check(true,why);}}async Task Refuse(Func<Task> a,string why){try{await a();throw new Exception("accepted "+why);}catch(Exception e)when(e is ArgumentException or IOException or InvalidDataException or OperationCanceledException){Check(true,why);}}
 var root=Path.Combine(Environment.GetEnvironmentVariable("PHOTOTRAIL_TEST_OUTPUT")!,"location-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Environment.SetEnvironmentVariable("PHOTOTRAIL_INPLACE_HISTORY",Path.Combine(root,"history"));Environment.SetEnvironmentVariable("PHOTOTRAIL_RENAME_COUNTERS",Path.Combine(root,"counters.json"));
 PhotoDocument Doc(string name,double longitude,string? datum="WGS-84",bool coords=true){var path=Path.Combine(root,name);File.WriteAllText(path,"synthetic source "+name);var data=new Dictionary<string,object>{{"File:FileType","JPEG"},{"XMP-photoshop:City","已有城市"},{"XMP-dc:Title","无关标题"}};if(coords){data["GPS:GPSLatitude"]=30;data["GPS:GPSLongitude"]=longitude;if(datum is not null)data["GPS:GPSMapDatum"]=datum;}var d=(PhotoDocument)typeof(PhotoDocument).GetConstructors(BindingFlags.NonPublic|BindingFlags.Instance).Single().Invoke(new object?[]{path,null,JsonSerializer.SerializeToElement(data),null,PhotoDocument.HashAsync(path).GetAwaiter().GetResult(),null});typeof(PhotoDocument).GetProperty("Iptc",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(d,new MetadataIptc());return d;}
 var a=Doc("a.jpg",120);var b=Doc("b.jpg",121);a.SetDraft(new Dictionary<string,string>{{"XMP-dc:Title","旧草稿"}});var input=new LocationValues("手填国家","手填省州","新城市","手填地点","CHN",Independent:true);var plan=await LocationAdoptionPlan.CreateAsync([a,b],input);Check(plan.Rows.Select(r=>r.Gps.Longitude).SequenceEqual(new[]{120d,121d}),"each own distinct GPS frozen");Check(plan.Rows.All(r=>!r.Fields.ContainsKey("XMP-photoshop:City")),"fill gaps keeps existing words");Check(a.Draft.Count==1&&a.Draft["XMP-dc:Title"]=="旧草稿","preview preserves unrelated draft");plan.Require([a,b]);Check(true,"exact frozen set current");Reject(()=>plan.Require([b,a]),"selection order changed");
 var overwrite=await LocationAdoptionPlan.CreateAsync([a,b],input with{Overwrite=true});Check(overwrite.Rows.All(r=>r.Fields["XMP-photoshop:City"]=="新城市"),"explicit overwrite");var clone=a.BatchSnapshot();clone.StageDraft(overwrite.Rows[0].Fields);Check(clone.Value("XMP-dc:Title")=="旧草稿"&&clone.Position()==a.Position()&&clone.Draft.Keys.All(t=>!t.StartsWith("XMP-exif:GPS")),"region adoption preserves GPS and unrelated draft");
 a.SetDraft(new Dictionary<string,string>{{"XMP-photoshop:Country","外部草稿"}});Reject(()=>plan.Require([a,b]),"revision changed");a.ClearDraft();var fresh=await LocationAdoptionPlan.CreateAsync([a],input);a.SetDraft(PhotoDocument.PositionChanges(new(122,31),null,"MANUAL"));Reject(()=>fresh.Require([a]),"GPS changed after freeze");a.ClearDraft();fresh=await LocationAdoptionPlan.CreateAsync([a],input);var t=File.GetLastWriteTimeUtc(a.FilePath);File.SetLastWriteTimeUtc(a.FilePath,t.AddSeconds(1));Reject(()=>fresh.Require([a]),"sameSHA system version changed");File.SetLastWriteTimeUtc(a.FilePath,t);
 foreach(var bad in new[]{input with{Independent=false},input with{Origin="google"},input with{CountryCode="CN"},input with{CountryCode="chn"},input with{Iptc=true,CountryCode="CN"},input with{Country="",State="",City="",Sublocation="",CountryCode=""}})Reject(()=>bad.Fields(),"origin/code/input boundary");Check((input with{Iptc=true,CountryCode="CHN"}).Fields()["IPTC:Country-PrimaryLocationCode"]=="CHN","explicit3letter no inferred mapping");Reject(()=>(input with{Iptc=true,CountryCode="CHN",City=new string('中',11)}).Fields(),"IPTC32bytes boundary");
 foreach(var d in new[]{Doc("unknown.jpg",120,null),Doc("datum.jpg",120,"GCJ-02"),Doc("missing.jpg",120,coords:false)})await Refuse(()=>LocationAdoptionPlan.CreateAsync([d],input),"unknown/missing/nonWGS refused");var failed=Doc("failed.jpg",120);failed.InspectionError="synthetic read failure";await Refuse(()=>LocationAdoptionPlan.CreateAsync([failed],input),"failed read refused");using var cancel=new CancellationTokenSource();cancel.Cancel();await Refuse(()=>LocationAdoptionPlan.CreateAsync([b],input,cancel.Token),"cancel no plan");Check(b.Draft.Count==0,"failed/cancel never clears fields");Console.WriteLine($"{n} R09b manual-source/GPS/revision/type assertions passed; no service or metadata writes.");
 }
